$edge = @("C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe","C:\Program Files\Microsoft\Edge\Application\msedge.exe") | Where-Object { Test-Path $_ } | Select-Object -First 1; if($edge){ Write-Output "EDGE:$edge" } else { Write-Output "NOEDGE" }
$chrome = @("C:\Program Files\Google\Chrome\Application\chrome.exe","C:\Program Files (x86)\Google\Chrome\Application\chrome.exe") | Where-Object { Test-Path $_ } | Select-Object -First 1; if($chrome){ Write-Output "CHROME:$chrome" } else { Write-Output "NOCHROME" }
Get-ChildItem D:\out\*.html | Select-Object Name,Length

